+
+The default source is `db/migrations`, relative to the current working directory.
+The binary reads migration files at runtime and applies pending up migrations.
+It returns `{"source":"db/migrations"}` on stdout after success, or the existing
+JSON error envelope on stderr with exit code 1 after failure. The response's
+`source` is the supplied path. Use SQLx CLI for adding, inspecting, or reverting
+migrations. The wrapper does not read `sqlx.toml`; it fixes the same history table
+at `public._sqlx_migrations` and retains SQLx's locking and checksum checks.
+
 Commands read the root `.env`. Set `DATABASE_URL` explicitly to target another
 database. The root [`sqlx.toml`](../sqlx.toml) fixes the history table at
 `public._sqlx_migrations`, regardless of the connection's search path.
//! JSON command results and their conversion to CLI output.

use schemars::JsonSchema;
use serde::Serialize;
use std::{
    io::{self, Write},
    process::ExitCode,
};

/// Generic JSON success response.
///
/// Payloads must expose their JSON schema as well as their serialization.
///
/// ```compile_fail
/// use exposed::inbound::cli::CliSuccess;
/// #[derive(serde::Serialize)]
/// struct Undocumented { count: usize }
/// let _ = CliSuccess::new(Undocumented { count: 1 });
/// ```
pub struct CliSuccess<S: Serialize + JsonSchema> {
    response: S,
}

impl<S: Serialize + JsonSchema> CliSuccess<S> {
    /// Creates a success response with a typed payload.
    pub const fn new(response: S) -> Self {
        Self { response }
    }
}

/// A serialized success or the original command failure.
pub struct Response(anyhow::Result<Vec<u8>>);

#[derive(Serialize, JsonSchema)]
pub(super) struct ErrorResponse {
    error: ErrorMessage,
}

#[derive(Serialize, JsonSchema)]
struct ErrorMessage {
    message: String,
}

impl Response {
    /// Writes one JSON document to stdout on success or stderr on failure.
    ///
    /// # Errors
    /// Returns an error if the selected output writer fails.
    pub fn write_to(self, mut stdout: impl Write, mut stderr: impl Write) -> io::Result<ExitCode> {
        let (mut bytes, writer, code): (_, &mut dyn Write, _) = match self.0 {
            Ok(bytes) => (bytes, &mut stdout, ExitCode::SUCCESS),
            Err(error) => {
                let payload = ErrorResponse {
                    error: ErrorMessage {
                        message: format!("{error:#}"),
                    },
                };
                let bytes = serde_json::to_vec(&payload).map_err(io::Error::other)?;
                (bytes, &mut stderr, ExitCode::FAILURE)
            }
        };
        bytes.push(b'\n');
        writer.write_all(&bytes)?;
        Ok(code)
    }
}

/// Converts a typed command result to a CLI response.
///
/// Wrap success payloads in [`CliSuccess`] before converting them.
///
/// ```compile_fail
/// use exposed::inbound::cli::IntoResponse;
/// "arbitrary text".into_response();
/// ```
pub trait IntoResponse {
    /// Converts this value to a response for the CLI boundary.
    fn into_response(self) -> Response;
}

impl IntoResponse for Response {
    fn into_response(self) -> Response {
        self
    }
}

impl<S: Serialize + JsonSchema> IntoResponse for CliSuccess<S> {
    fn into_response(self) -> Response {
        Response(serde_json::to_vec(&self.response).map_err(Into::into))
    }
}

impl<T, E> IntoResponse for Result<T, E>
where
    T: IntoResponse,
    E: Into<anyhow::Error>,
{
    fn into_response(self) -> Response {
        match self {
            Ok(value) => value.into_response(),
            Err(error) => Response(Err(error.into())),
        }
    }
}
//! Config for CLI

use anyhow::Context;
use std::{fs::read_to_string, io::Error as IoError, path::PathBuf};
use thiserror::Error;

use serde::{Deserialize, Serialize};

/// Environment configuration for CLI commands that use the database.
pub struct DataConfig {
    /// PostgreSQL connection string.
    pub connection_string: String,
}

impl DataConfig {
    /// Reads the database connection string from the environment.
    ///
    /// # Errors
    /// Returns an error if `DATABASE_URL` is missing or contains non-Unicode data.
    pub fn from_env() -> anyhow::Result<Self> {
        Ok(Self {
            connection_string: std::env::var("DATABASE_URL").context("DATABASE_URL must be set")?,
        })
    }
}

/// Configuration for capturing declarations for the stored member cohort.
#[derive(Serialize, Deserialize)]
pub struct DeclarationFetcherConfig {
    /// Root directory for ingestion datasets.
    pub data_dir: PathBuf,
    /// Nonzero API page size; validated when constructing the HTTP adapter.
    pub batch_size: u8,
}

impl TryFrom<&PathBuf> for DeclarationFetcherConfig {
    type Error = CliConfigError;

    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        Ok(rust_yaml::from_str(&raw)?)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct FetcherConfig {
    /// Size of API batches
    pub batch_size: u8,
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for FetcherConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct LoaderConfig {
